def run(input):
    import subprocess
    cmd = (input.get('setup_command') or '').strip()
    if not cmd:
        return {'ran': False, 'note': '无 setup 命令，跳过'}
    try:
        r = subprocess.run(['bash', '-c', cmd], cwd=input['worktree_dir'], capture_output=True, text=True, timeout=int(input.get('setup_timeout_secs', 1800)))
        tail = ((r.stdout or '') + (r.stderr or ''))[-500:]
        if r.returncode != 0:
            return {'ran': True, 'ok': False, 'note': 'setup 失败', 'error': tail}
        return {'ran': True, 'ok': True, 'note': 'setup 完成', 'tail': tail}
    except subprocess.TimeoutExpired:
        return {'ran': True, 'ok': False, 'note': 'setup 超时'}

def run(input):
    import subprocess
    r = subprocess.run(['git','status','--porcelain'], cwd=input['worktree_dir'], capture_output=True, text=True, timeout=30)
    has = bool(r.stdout.strip())
    text = input.get('impl_text') or ''
    return {'has_changes': has, 'blocked': (not has) or text.startswith('BLOCKED'), 'impl_summary': text[:200]}

