def run(input):
    import subprocess
    wt = input['worktree_dir']
    base = input['base_branch']
    def sh(args, t=120):
        return subprocess.run(args, cwd=wt, capture_output=True, text=True, timeout=t)
    sh(['git', 'fetch', 'origin'])
    behind = sh(['git', 'rev-list', '--count', 'HEAD..origin/%s' % base])
    n = (behind.stdout or '0').strip()
    if behind.returncode != 0 or n == '0':
        return {'synced': False, 'note': '基线无新提交'}
    dirty = (sh(['git', 'status', '--porcelain']).stdout or '').strip()
    if dirty:
        sh(['git', 'stash', 'push', '-u', '-m', 'issue-pipeline-sync'])
    r = sh(['git', 'merge', '--ff-only', 'origin/%s' % base])
    if r.returncode != 0:
        if dirty:
            sh(['git', 'stash', 'pop'])
        return {'synced': False, 'note': 'ff 同步失败', 'error': (r.stderr or '')[-300:]}
    popped = ''
    if dirty:
        p = sh(['git', 'stash', 'pop'], 300)
        if p.returncode != 0:
            return {'synced': False, 'note': 'stash pop 有冲突，需人工处理', 'error': (p.stderr or '')[-300:]}
        popped = '；工作区改动已从 stash 恢复'
    return {'synced': True, 'note': '基线前进 %s 个提交，已同步%s' % (n, popped)}

def run(input):
    import subprocess
    r = subprocess.run(['git', 'diff', '--name-only', 'HEAD'], cwd=input['worktree_dir'], capture_output=True, text=True, timeout=60)
    files = [f for f in r.stdout.splitlines() if f.strip()]
    bad = [f for f in files if f.startswith('.github/') or f.startswith('.worktrees/') or '..' in f or f.startswith('/')]
    n = subprocess.run(['git', 'diff', '--shortstat', 'HEAD'], cwd=input['worktree_dir'], capture_output=True, text=True, timeout=60)
    oversized = False
    if n.stdout and 'insertion' in n.stdout:
        try:
            oversized = int(n.stdout.split('insertion')[0].strip().split()[-1].replace('+','').replace(',','')) > 800
        except Exception:
            oversized = False
    return {'ok': (not bad) and (not oversized), 'violations': bad, 'oversized': oversized}

def run(input):
    import subprocess
    try:
        r = subprocess.run(['python', '-m', 'issue_keeper', 'internal', 'move', input['repo_full'], str(input['issue_number']), 'review'], capture_output=True, text=True, timeout=60)
        return {'kanban_ok': r.returncode == 0}
    except Exception:
        return {'kanban_ok': False}
